import java.util.*;

public class Expire {
    public static void main(String[] args) {
        List<Integer> ages = new ArrayList<>(List.of(5, 40, 7, 50, 60));

        Iterator<Integer> it = ages.iterator();
        while (it.hasNext()) {
            if (it.next() > 30) it.remove();          // the iterator stays in sync.
        }
        System.out.println(ages);                     // [5, 7]

        List<Integer> more = new ArrayList<>(List.of(5, 40, 7, 50, 60));
        more.removeIf(a -> a > 30);                   // bulk operation, same result.
        System.out.println(more);                     // [5, 7]

        List<Integer> frozen = List.copyOf(more);     // unmodifiable, independent copy.
        try { frozen.add(1); }
        catch (UnsupportedOperationException e) { System.out.println("read-only"); }
    }
}
```

